const toast=document.querySelector('#toast');
const login=document.querySelector('#adminLogin');
const panel=document.querySelector('#reviewPanel');
const list=document.querySelector('#verificationList');
const pendingCount=document.querySelector('#pendingCount');
const lastUpdated=document.querySelector('#lastUpdated');
const securityDialog=document.querySelector('#securityDialog');
const moderationPanel=document.querySelector('#moderationPanel');
const moderationList=document.querySelector('#moderationList');
let adminView='verification';

const showToast=(title,copy)=>{toast.querySelector('b').textContent=title;toast.querySelector('.toast-copy').textContent=copy;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),3800)};
async function api(path,options={}){const response=await fetch(path,{credentials:'include',...options,headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});const data=response.status===204?null:await response.json().catch(()=>({}));if(!response.ok){const error=new Error(data?.message||'Operación rechazada.');error.status=response.status;throw error}return data}
function setBusy(button,busy,label='Procesando…'){if(!button.dataset.label)button.dataset.label=button.innerHTML;button.disabled=busy;button.innerHTML=busy?label:button.dataset.label}
function escapeHtml(value){const element=document.createElement('span');element.textContent=String(value??'');return element.innerHTML}
function roleLabel(role){return role==='company'?'Empresa':role==='professional'?'Profesional':'Cliente'}

async function load(){
  adminView='verification';moderationPanel.hidden=true;list.hidden=false;
  list.innerHTML='<div class="loading-state"><span></span><p>Cargando solicitudes…</p></div>';
  login.hidden=true;panel.hidden=false;
  const rows=await api('/api/admin/verifications');
  pendingCount.textContent=String(rows.length).padStart(2,'0');
  lastUpdated.textContent=`Actualizado ${new Date().toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}`;
  list.innerHTML=rows.length?rows.map((row,index)=>`<article class="review-card" data-user="${escapeHtml(row.user_id)}"><span class="review-number">${String(index+1).padStart(2,'0')}</span><div><h2>${escapeHtml(row.legal_name)}</h2><div class="review-meta"><b>${roleLabel(row.role)}</b><span>@${escapeHtml(row.username)}</span><span>${escapeHtml(row.email)}</span><span>${new Date(row.submitted_at).toLocaleString('es-CL')}</span></div><div class="document-reference"><b>Referencia documental</b><br>${escapeHtml(row.document_reference)}${row.registration_reference?`<br><b>Registro o credencial</b><br>${escapeHtml(row.registration_reference)}`:''}</div></div><div class="review-actions"><textarea maxlength="800" aria-label="Motivo de la decisión para ${escapeHtml(row.legal_name)}" placeholder="Motivo obligatorio de la decisión"></textarea><button data-status="verified">Aprobar ticket</button><button class="reject" data-status="rejected">Rechazar solicitud</button></div></article>`).join(''):'<div class="empty-state"><strong>Todo revisado.</strong><span>No hay solicitudes pendientes en este momento.</span></div>';
  list.querySelectorAll('[data-status]').forEach(button=>button.addEventListener('click',()=>review(button)));
}

async function loadModeration(){adminView='moderation';list.hidden=true;moderationPanel.hidden=false;moderationList.innerHTML='<div class="loading-state"><span></span><p>Cargando controles…</p></div>';const data=await api('/api/admin/moderation');pendingCount.textContent=String(data.reports.length).padStart(2,'0');lastUpdated.textContent=`Actualizado ${new Date().toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}`;const reportCards=data.reports.map((item,index)=>`<article class="review-card" data-report="${item.id}"><span class="review-number">R${String(index+1).padStart(2,'0')}</span><div><h2>Reporte sobre ${escapeHtml(item.target_type)}</h2><div class="review-meta"><b>Pendiente</b><span>Reportado por @${escapeHtml(item.reporter_username)}</span></div><div class="document-reference">${escapeHtml(item.reason)}</div></div><div class="review-actions"><textarea maxlength="800" placeholder="Resolución obligatoria"></textarea><button data-report-status="resolved">Marcar resuelto</button><button class="reject" data-report-status="dismissed">Descartar</button></div></article>`);const userCards=data.users.map(user=>`<article class="review-card" data-user="${user.id}"><span class="review-number">U</span><div><h2>${escapeHtml(user.display_name)}</h2><div class="review-meta"><b>${roleLabel(user.role)}</b><span>@${escapeHtml(user.username)}</span><span>${escapeHtml(user.verification_status)}</span></div></div><div class="review-actions"><textarea maxlength="800" placeholder="Motivo obligatorio"></textarea><button data-user-action="${user.verification_status==='suspended'?'restore':'suspend'}">${user.verification_status==='suspended'?'Restaurar cuenta':'Suspender cuenta'}</button></div></article>`);const projectCards=data.projects.map(project=>`<article class="review-card" data-project="${project.id}"><span class="review-number">P</span><div><h2>${escapeHtml(project.title)}</h2><div class="review-meta"><b>${escapeHtml(project.status)}</b><span>@${escapeHtml(project.username)}</span></div></div><div class="review-actions"><textarea maxlength="800" placeholder="Motivo obligatorio"></textarea><button data-project-action="${project.status==='suspended'?'restore':'suspend'}">${project.status==='suspended'?'Restaurar publicación':'Bajar publicación'}</button></div></article>`);moderationList.innerHTML=[...reportCards,...userCards,...projectCards].join('')||'<div class="empty-state"><strong>Sin elementos.</strong></div>';moderationList.querySelectorAll('[data-user-action]').forEach(button=>button.addEventListener('click',()=>moderate(button,'user')));moderationList.querySelectorAll('[data-project-action]').forEach(button=>button.addEventListener('click',()=>moderate(button,'project')));moderationList.querySelectorAll('[data-report-status]').forEach(button=>button.addEventListener('click',()=>resolveReport(button)))}
async function moderate(button,type){const card=button.closest('.review-card');const reason=card.querySelector('textarea').value.trim();if(!reason)return showToast('Falta el motivo','Toda acción administrativa debe quedar fundamentada.');const action=button.dataset.userAction||button.dataset.projectAction;setBusy(button,true);try{const id=type==='user'?card.dataset.user:card.dataset.project;await api(`/api/admin/moderation/${type==='user'?'users':'projects'}/${id}`,{method:'POST',body:JSON.stringify({action,reason})});showToast('Moderación registrada','El cambio quedó guardado en la bitácora.');await loadModeration()}catch(error){showToast('No se pudo moderar',error.message);setBusy(button,false)}}
async function resolveReport(button){const card=button.closest('.review-card');const reason=card.querySelector('textarea').value.trim();if(!reason)return showToast('Falta la resolución','Explica cómo se resolvió el reporte.');setBusy(button,true);try{await api(`/api/admin/moderation/reports/${card.dataset.report}`,{method:'POST',body:JSON.stringify({status:button.dataset.reportStatus,reason})});showToast('Reporte actualizado','La resolución quedó auditada.');await loadModeration()}catch(error){showToast('No se pudo resolver',error.message);setBusy(button,false)}}

async function review(button){const card=button.closest('.review-card');const reason=card.querySelector('textarea').value.trim();if(!reason)return showToast('Falta el motivo','Registra el fundamento antes de decidir.');setBusy(button,true);card.querySelectorAll('button').forEach(item=>item.disabled=true);try{await api(`/api/admin/verifications/${card.dataset.user}/review`,{method:'POST',body:JSON.stringify({status:button.dataset.status,reason})});showToast('Decisión registrada','La cuenta y la bitácora fueron actualizadas.');await load()}catch(error){showToast('No se pudo revisar',error.message);card.querySelectorAll('button').forEach(item=>item.disabled=false);setBusy(button,false)}}

document.querySelector('#adminLoginForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector('[type="submit"]');if(!form.checkValidity())return form.reportValidity();setBusy(button,true,'Verificando…');try{await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();await load()}catch(error){showToast('Acceso rechazado',error.message)}finally{setBusy(button,false)}});
document.querySelector('#refreshButton').addEventListener('click',async event=>{setBusy(event.currentTarget,true,'Actualizando…');try{await (adminView==='moderation'?loadModeration():load())}catch(error){showToast('No se pudo actualizar',error.message)}finally{setBusy(event.currentTarget,false)}});
document.querySelector('#moderationButton').addEventListener('click',async()=>{if(adminView==='moderation'){adminView='verification';moderationPanel.hidden=true;list.hidden=false;await load()}else await loadModeration()});
document.querySelector('#securityButton').addEventListener('click',()=>securityDialog.showModal());
document.querySelector('#closeSecurityButton').addEventListener('click',()=>securityDialog.close());
securityDialog.addEventListener('click',event=>{if(event.target===securityDialog)securityDialog.close()});
document.querySelector('#logoutButton').addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST'});panel.hidden=true;login.hidden=false;showToast('Sesión cerrada','El acceso administrativo se cerró correctamente.')}catch(error){showToast('No se pudo cerrar',error.message)}});
document.querySelector('#adminPasswordForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;if(!form.checkValidity())return form.reportValidity();const button=form.querySelector('[type="submit"]');setBusy(button,true);try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();securityDialog.close();panel.hidden=true;login.hidden=false;showToast('Contraseña actualizada','Cerramos todas las sesiones. Ingresa nuevamente.')}catch(error){showToast('No se pudo cambiar',error.message)}finally{setBusy(button,false)}});

api('/api/auth/me').then(user=>{if(user.role!=='admin')throw new Error('not_admin');return load()}).catch(()=>{panel.hidden=true;login.hidden=false});
